"""Eval cases: schema, loader and validator.

An :class:`EvalCase` is one integration-mapping task: a source object (all of its
fields, distractors included) and a target object (the writable fields in scope
of the integration), plus the gold mapping for every target field.

Field paths are relative to the object: ``address.city``, ``lines[].amount``.
Segments are ``[A-Za-z0-9_]+`` with an optional ``[]`` array marker.

Suites
------
* ``synthetic``   generated by :mod:`app.platform.evals.synthetic` (seeded).
* ``handlabeled`` JSON files in ``datasets/handlabeled/``. Each file holds a list
  of cases in *compact* form: ``"source": "crm-sf/Account"`` refers to an object
  schema in ``_schemas.json`` (the full source schema is used, so every real
  field is a candidate), and the target fields are exactly the gold targets,
  resolved from the target schema. Expanded (full) cases are accepted too.

Labeling rules (hand-labeled set)
---------------------------------
Labels were written from the semantics of the (public-API-styled) fields, before
and independently of any predictor run. Predictor output was never used to
change a label.

1. ``source`` is the single source field whose value - possibly after one
   deterministic transform - populates the target. If the target genuinely
   combines several fields (full name from first + last), the gold source is the
   primary component and the transform is ``concat``.
2. ``source`` is ``null`` when no source field carries the information: the
   target's own system-assigned keys, target-only configuration (templates,
   collection settings, tax codes), constants set by the integration itself, or
   data the source object simply does not have.
3. A deprecated source field is never gold when its replacement exists.
4. The target's external-reference field (``metadata.crm_id``, ``externalId``)
   maps from the source's primary key. The target's own primary key maps to null.
5. Billing (bill-to) data maps to billing fields and ship-to data to shipping
   fields; tax jurisdiction comes from ship-to (destination-based sales tax).
6. ``transform`` uses the vocabulary in :data:`TRANSFORMS`; ``null`` means a
   direct copy (including trivially compatible types, e.g. decimal -> number).
   ``lookup`` means the value must be resolved through another system (an id
   in the target system, a reference record). A templated string built from
   one field ("Please sign: {Name}") is ``concat``.
7. When two source fields carry the same information in different
   representations (``BillingCountry`` name vs ``BillingCountryCode``), gold is
   the one that needs no transform.
8. Cases are grouped into ``sequence`` / ``step`` when they are successive
   integrations between the same (or same-family) systems; the learning curve
   replays them in step order.
"""

from __future__ import annotations

import json
import re
from collections.abc import Iterable
from pathlib import Path
from typing import Literal

from pydantic import BaseModel, ConfigDict, Field, ValidationError, model_validator

DATASETS_DIR = Path(__file__).parent / "datasets"
HANDLABELED_DIR = DATASETS_DIR / "handlabeled"
SCHEMAS_FILE = "_schemas.json"

Suite = Literal["synthetic", "handlabeled", "conventions"]
SUITES: tuple[Suite, ...] = ("synthetic", "handlabeled")
Difficulty = Literal["easy", "medium", "hard"]
FieldType = Literal["string", "integer", "number", "boolean", "date", "datetime", "enum", "object", "array"]
SampleValue = str | int | float | bool | None

#: Canonical transform vocabulary. ``None`` (no transform) means direct copy.
TRANSFORMS: frozenset[str] = frozenset(
    {
        "cents_to_decimal",
        "decimal_to_cents",
        "epoch_to_iso_date",
        "epoch_to_iso_datetime",
        "iso_to_epoch",
        "date_format",
        "enum_map",
        "currency_name_to_code",
        "currency_code_to_name",
        "country_name_to_iso2",
        "country_iso2_to_name",
        "percent_to_fraction",
        "fraction_to_percent",
        "to_upper",
        "to_lower",
        "to_string",
        "to_number",
        "concat",
        "split_first",
        "split_last",
        "first_item",
        "geocode",
        "lookup",
        "negate",
        "other",
    }
)

_SEGMENT = re.compile(r"^[A-Za-z0-9_]+(\[\])?$")


class DatasetError(ValueError):
    """A case file is malformed or a case violates the labeling contract."""


def validate_path(path: str) -> str:
    parts = path.split(".")
    if not parts or not all(_SEGMENT.match(p) for p in parts):
        raise ValueError(f"invalid field path {path!r}")
    return path


class EvalField(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)

    path: str
    type: FieldType = "string"
    #: Representation detail: cents, decimal, iso8601_date, iso8601_datetime, epoch_s,
    #: iso4217, currency_name, country_iso2, country_name, email, phone, percent, fraction ...
    format: str | None = None
    description: str | None = None
    sample: SampleValue = None
    enum: tuple[str, ...] | None = None
    deprecated: bool = False

    @model_validator(mode="after")
    def _check(self) -> EvalField:
        validate_path(self.path)
        return self


class GoldMapping(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)

    target: str
    source: str | None = None
    transform: str | None = None

    @model_validator(mode="after")
    def _check(self) -> GoldMapping:
        if self.transform is not None and self.transform not in TRANSFORMS:
            raise ValueError(f"unknown transform {self.transform!r} for target {self.target!r}")
        if self.source is None and self.transform is not None:
            raise ValueError(f"target {self.target!r}: a null source cannot have a transform")
        return self


class ObjectRef(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)

    #: Concrete system id (vendor instance), e.g. ``crm-sf`` or ``billing-v3``.
    system: str
    #: System family: crm, billing, erp, accounting, esign, tax, marketing.
    kind: str
    #: Business object name in that system, e.g. ``Account`` or ``customer``.
    object: str


class CaseTags(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)

    difficulty: Difficulty
    #: Canonical object category: customer, contact, opportunity, contract, invoice, payment, address, line_item.
    category: str
    #: Naming family of the pair, e.g. ``salesforce-style->stripe-style`` or ``camel->snake``.
    vendor_family: str


class EvalCase(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)

    id: str
    suite: Suite
    source: ObjectRef
    target: ObjectRef
    source_fields: tuple[EvalField, ...]
    target_fields: tuple[EvalField, ...]
    gold: tuple[GoldMapping, ...]
    tags: CaseTags
    sequence: str | None = None
    step: int | None = None
    notes: str | None = None

    @model_validator(mode="after")
    def _check(self) -> EvalCase:
        problems = case_problems(self)
        if problems:
            raise ValueError(f"case {self.id}: " + "; ".join(problems))
        return self

    # ------------------------------------------------------------- helpers
    def source_field(self, path: str) -> EvalField | None:
        return next((f for f in self.source_fields if f.path == path), None)

    def target_field(self, path: str) -> EvalField | None:
        return next((f for f in self.target_fields if f.path == path), None)

    def gold_for(self, target: str) -> GoldMapping:
        for g in self.gold:
            if g.target == target:
                return g
        raise KeyError(f"case {self.id} has no gold for {target!r}")

    @property
    def n_gold_mapped(self) -> int:
        return sum(g.source is not None for g in self.gold)


def case_problems(case: EvalCase) -> list[str]:
    """Every violation of the dataset contract (empty list = valid)."""
    problems: list[str] = []
    for side, fields in (("source", case.source_fields), ("target", case.target_fields)):
        paths = [f.path for f in fields]
        dupes = sorted({p for p in paths if paths.count(p) > 1})
        if dupes:
            problems.append(f"duplicate {side} paths {dupes}")
    if not case.target_fields:
        problems.append("no target fields")
    source_by_path = {f.path: f for f in case.source_fields}
    target_paths = {f.path for f in case.target_fields}
    gold_targets = [g.target for g in case.gold]
    dup_gold = sorted({t for t in gold_targets if gold_targets.count(t) > 1})
    if dup_gold:
        problems.append(f"multiple gold entries for {dup_gold}")
    missing_gold = sorted(target_paths - set(gold_targets))
    if missing_gold:
        problems.append(f"target fields without gold {missing_gold}")
    unknown_targets = sorted(set(gold_targets) - target_paths)
    if unknown_targets:
        problems.append(f"gold targets not in target schema {unknown_targets}")
    for g in case.gold:
        if g.source is None:
            continue
        src = source_by_path.get(g.source)
        if src is None:
            problems.append(f"gold source {g.source!r} (for {g.target!r}) not in source schema")
        elif src.deprecated:
            problems.append(f"gold source {g.source!r} is deprecated (rule 3)")
    if (case.sequence is None) != (case.step is None):
        problems.append("sequence and step must be set together")
    return problems


# ------------------------------------------------------------------ loading
class _CompactCase(BaseModel):
    """Hand-labeled file form: object schemas by reference, targets = gold targets."""

    model_config = ConfigDict(extra="forbid")

    id: str
    source: str
    target: str
    tags: CaseTags
    gold: list[GoldMapping]
    sequence: str | None = None
    step: int | None = None
    notes: str | None = None


class _ObjectSchema(BaseModel):
    model_config = ConfigDict(extra="forbid")

    system: str
    kind: str
    object: str
    description: str | None = None
    fields: list[EvalField] = Field(default_factory=list)


def load_schemas(path: Path) -> dict[str, _ObjectSchema]:
    raw = _read_json(path)
    if not isinstance(raw, dict):
        raise DatasetError(f"{path}: expected an object of schemas")
    out: dict[str, _ObjectSchema] = {}
    for key, value in raw.items():
        try:
            schema = _ObjectSchema.model_validate(value)
        except ValidationError as exc:
            raise DatasetError(f"{path}: schema {key!r}: {exc}") from exc
        if key != f"{schema.system}/{schema.object}":
            raise DatasetError(f"{path}: schema key {key!r} must be '<system>/<object>'")
        out[key] = schema
    return out


def _expand(compact: _CompactCase, schemas: dict[str, _ObjectSchema], suite: Suite) -> EvalCase:
    for ref in (compact.source, compact.target):
        if ref not in schemas:
            raise DatasetError(f"case {compact.id}: unknown schema {ref!r}")
    src, tgt = schemas[compact.source], schemas[compact.target]
    tgt_by_path = {f.path: f for f in tgt.fields}
    unknown = [g.target for g in compact.gold if g.target not in tgt_by_path]
    if unknown:
        raise DatasetError(f"case {compact.id}: gold targets {unknown} not in schema {compact.target}")
    return EvalCase(
        id=compact.id,
        suite=suite,
        source=ObjectRef(system=src.system, kind=src.kind, object=src.object),
        target=ObjectRef(system=tgt.system, kind=tgt.kind, object=tgt.object),
        source_fields=tuple(src.fields),
        target_fields=tuple(tgt_by_path[g.target] for g in compact.gold),
        gold=tuple(compact.gold),
        tags=compact.tags,
        sequence=compact.sequence,
        step=compact.step,
        notes=compact.notes,
    )


def _read_json(path: Path) -> object:
    try:
        with path.open(encoding="utf-8") as fh:
            return json.load(fh)
    except json.JSONDecodeError as exc:
        raise DatasetError(f"{path}: invalid JSON: {exc}") from exc


def load_case_file(
    path: Path, schemas: dict[str, _ObjectSchema] | None = None, suite: Suite = "handlabeled"
) -> list[EvalCase]:
    raw = _read_json(path)
    items = raw if isinstance(raw, list) else [raw]
    cases: list[EvalCase] = []
    for i, item in enumerate(items):
        if not isinstance(item, dict):
            raise DatasetError(f"{path}[{i}]: expected an object")
        try:
            if isinstance(item.get("source"), str):
                if schemas is None:
                    raise DatasetError(f"{path}[{i}]: compact case needs {SCHEMAS_FILE}")
                cases.append(_expand(_CompactCase.model_validate(item), schemas, suite))
            else:
                cases.append(EvalCase.model_validate({"suite": suite, **item}))
        except ValidationError as exc:
            raise DatasetError(f"{path}[{i}] ({item.get('id', '?')}): {exc}") from exc
    return cases


def load_directory(directory: Path, suite: Suite = "handlabeled") -> list[EvalCase]:
    """Load every ``*.json`` case file in ``directory`` (``_schemas.json`` = shared schemas)."""
    if not directory.is_dir():
        raise DatasetError(f"dataset directory {directory} does not exist")
    schema_path = directory / SCHEMAS_FILE
    schemas = load_schemas(schema_path) if schema_path.exists() else None
    cases: list[EvalCase] = []
    for path in sorted(directory.glob("*.json")):
        if path.name == SCHEMAS_FILE:
            continue
        cases.extend(load_case_file(path, schemas, suite))
    ids = [c.id for c in cases]
    dupes = sorted({i for i in ids if ids.count(i) > 1})
    if dupes:
        raise DatasetError(f"duplicate case ids {dupes}")
    return sorted(cases, key=sort_key)


def load_handlabeled() -> list[EvalCase]:
    return load_directory(HANDLABELED_DIR, "handlabeled")


def sort_key(case: EvalCase) -> tuple[str, int, str]:
    return (case.sequence or "~", case.step or 0, case.id)


def group_sequences(cases: Iterable[EvalCase]) -> dict[str, list[EvalCase]]:
    """Cases with a ``sequence`` grouped and ordered by ``step``."""
    groups: dict[str, list[EvalCase]] = {}
    for case in cases:
        if case.sequence is not None:
            groups.setdefault(case.sequence, []).append(case)
    return {k: sorted(v, key=lambda c: (c.step or 0, c.id)) for k, v in sorted(groups.items())}


def dataset_stats(cases: Iterable[EvalCase]) -> dict[str, int]:
    cases = list(cases)
    return {
        "cases": len(cases),
        "gold_targets": sum(len(c.gold) for c in cases),
        "gold_mapped": sum(c.n_gold_mapped for c in cases),
        "gold_null": sum(len(c.gold) - c.n_gold_mapped for c in cases),
        "with_transform": sum(1 for c in cases for g in c.gold if g.transform is not None),
    }
